package com.dss26.payments.gateway.events;

import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import org.apache.avro.generic.GenericRecord;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;

import com.dss26.payments.gateway.GatewayProperties;

@Component
public class AuthorisationEventPublisher {

    static final String REQUEST_ID_HEADER = "x-request-id";

    private static final Logger log = LoggerFactory.getLogger(AuthorisationEventPublisher.class);

    private final KafkaTemplate<String, GenericRecord> kafka;
    private final String topic;
    private final Duration sendTimeout;

    public AuthorisationEventPublisher(KafkaTemplate<String, GenericRecord> kafka, GatewayProperties properties) {
        this.kafka = kafka;
        this.topic = properties.topic();
        this.sendTimeout = properties.sendTimeout();
    }

    /**
     * Publishes the event keyed by card token and waits for the acknowledgement
     * (acks=all), so a 202 to the merchant means the authorisation is on the topic.
     */
    public void publish(String key, GenericRecord event, String requestId) {
        ProducerRecord<String, GenericRecord> record = new ProducerRecord<>(topic, key, event);
        if (requestId != null && !requestId.isBlank()) {
            record.headers().add(REQUEST_ID_HEADER, requestId.getBytes(StandardCharsets.UTF_8));
        }
        try {
            kafka.send(record).get(sendTimeout.toMillis(), TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new PublishFailedException("Interrupted publishing auth_id " + event.get("auth_id"), e);
        } catch (ExecutionException | TimeoutException e) {
            log.error("Publishing auth_id={} to {} failed", event.get("auth_id"), topic, e);
            throw new PublishFailedException("Could not publish auth_id " + event.get("auth_id"), e);
        }
    }
}

package com.dss26.payments.gateway.events;

import java.time.Instant;

import org.apache.avro.Schema;
import org.apache.avro.generic.GenericRecord;
import org.apache.avro.generic.GenericRecordBuilder;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import com.dss26.payments.gateway.GatewayProperties;
import com.dss26.payments.gateway.api.AuthorisationRequest;

/**
 * Builds the cards.authorisation.requested.v1 value for an accepted request.
 * Field names and types are those of src/main/avro/cards.authorisation.requested.v1.avsc.
 */
@Component
public class CardAuthEventMapper {

    private final Schema schema;
    private final String tier;

    @Autowired
    public CardAuthEventMapper(CardAuthSchema schema, GatewayProperties properties) {
        this(schema.schema(), properties.tier());
    }

    public CardAuthEventMapper(Schema schema, String tier) {
        this.schema = schema;
        this.tier = tier;
    }

    public GenericRecord toEvent(String authId, AuthorisationRequest request, Instant receivedAt) {
        return new GenericRecordBuilder(schema)
                .set("auth_id", authId)
                .set("card_token", request.cardToken())
                .set("merchant_id", request.merchantId())
                .set("amount", request.amount().toPlainString())
                .set("currency", request.currency())
                .set("ts", receivedAt.toEpochMilli())
                .set("risk_signals", request.riskSignals())
                .set("channel", request.channel().name())
                .set("tier", tier)
                .build();
    }
}

package com.dss26.payments.gateway.events;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;

import org.apache.avro.Schema;
import org.springframework.stereotype.Component;

/**
 * Value schema of cards.authorisation.requested.v1, parsed from the .avsc that is
 * packaged with the service (src/main/avro). The release pipeline registers the
 * same file, so the records we build and the subject's latest version agree.
 */
@Component
public class CardAuthSchema {

    static final String RESOURCE = "avro/cards.authorisation.requested.v1.avsc";

    private final Schema schema;

    public CardAuthSchema() {
        this.schema = load();
    }

    public Schema schema() {
        return schema;
    }

    public static Schema load() {
        try (InputStream in = CardAuthSchema.class.getClassLoader().getResourceAsStream(RESOURCE)) {
            if (in == null) {
                throw new IllegalStateException(RESOURCE + " is not on the classpath");
            }
            return new Schema.Parser().parse(in);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

