package com.dss26.payments.gateway.idempotency;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import com.dss26.payments.gateway.GatewayProperties;
import com.dss26.payments.gateway.api.AuthorisationRejectedException;

/**
 * Remembers which auth id was issued for an Idempotency-Key, so an acquirer
 * retrying after a timeout does not publish the same authorisation twice.
 * In memory per pod; merchants are pinned to pods by the load balancer.
 */
@Component
public class IdempotencyStore {

    private static final int SWEEP_EVERY = 10_000;

    private final Map<String, Entry> entries = new ConcurrentHashMap<>();
    private final Duration ttl;
    private final Clock clock;
    private int reservations;

    @Autowired
    public IdempotencyStore(GatewayProperties properties, Clock clock) {
        this(properties.idempotencyTtl(), clock);
    }

    public IdempotencyStore(Duration ttl, Clock clock) {
        this.ttl = ttl;
        this.clock = clock;
    }

    /**
     * Reserves {@code key} for {@code authId}. If the key was already used for an
     * equal request within the TTL, returns the auth id issued then and reserves
     * nothing.
     *
     * @throws AuthorisationRejectedException 409 if the key was used for a different request
     */
    public Optional<String> reserve(String key, Object request, String authId) {
        Instant now = clock.instant();
        sweepOccasionally(now);
        Entry winner = entries.compute(key, (k, existing) ->
                existing == null || existing.expiresAt().isBefore(now)
                        ? new Entry(request, authId, now.plus(ttl))
                        : existing);
        if (winner.authId().equals(authId)) {
            return Optional.empty();
        }
        if (!winner.request().equals(request)) {
            throw AuthorisationRejectedException.idempotencyConflict(key);
        }
        return Optional.of(winner.authId());
    }

    private synchronized void sweepOccasionally(Instant now) {
        if (++reservations % SWEEP_EVERY == 0) {
            entries.values().removeIf(entry -> entry.expiresAt().isBefore(now));
        }
    }

    private record Entry(Object request, String authId, Instant expiresAt) {
    }
}

package com.dss26.payments.gateway.policy;

import java.util.Currency;

import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;

import com.dss26.payments.gateway.api.AuthorisationRejectedException;
import com.dss26.payments.gateway.api.AuthorisationRequest;

/**
 * Business rules a request must pass before it is published, beyond what bean
 * validation can express.
 */
@Component
public class AuthorisationPolicy {

    /**
     * Rejects amounts with more decimal places than the currency's minor unit
     * (JPY 0, EUR 2, KWD 3). Downstream systems settle in minor units, so an
     * over-precise amount must be refused at the edge rather than rounded later.
     */
    public void check(AuthorisationRequest request) {
        Currency currency;
        try {
            currency = Currency.getInstance(request.currency());
        } catch (IllegalArgumentException e) {
            throw new AuthorisationRejectedException(HttpStatus.UNPROCESSABLE_ENTITY, "unsupported_currency",
                    request.currency() + " is not an ISO 4217 currency code");
        }
        int minorDigits = Math.max(currency.getDefaultFractionDigits(), 0);
        if (request.amount().stripTrailingZeros().scale() > minorDigits) {
            throw new AuthorisationRejectedException(HttpStatus.UNPROCESSABLE_ENTITY, "invalid_amount_scale",
                    "%s allows %d decimal places, got %s".formatted(
                            currency.getCurrencyCode(), minorDigits, request.amount().toPlainString()));
        }
    }
}

package com.dss26.payments.gateway.policy;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.LongSupplier;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import com.dss26.payments.gateway.GatewayProperties;

/**
 * Token bucket per merchant_id, so one merchant's retry storm cannot starve the
 * others. Per pod: the load balancer pins a merchant to a pod.
 */
@Component
public class MerchantRateLimiter {

    private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();
    private final double perSecond;
    private final double burst;
    private final LongSupplier nanoTime;

    @Autowired
    public MerchantRateLimiter(GatewayProperties properties) {
        this(properties.rateLimit().perSecond(), properties.rateLimit().burst(), System::nanoTime);
    }

    public MerchantRateLimiter(int perSecond, int burst, LongSupplier nanoTime) {
        this.perSecond = perSecond;
        this.burst = burst;
        this.nanoTime = nanoTime;
    }

    public boolean tryAcquire(String merchantId) {
        return buckets.computeIfAbsent(merchantId, id -> new Bucket(burst, nanoTime.getAsLong())).tryTake();
    }

    private final class Bucket {

        private double tokens;
        private long refilledAt;

        private Bucket(double tokens, long now) {
            this.tokens = tokens;
            this.refilledAt = now;
        }

        synchronized boolean tryTake() {
            long now = nanoTime.getAsLong();
            tokens = Math.min(burst, tokens + (now - refilledAt) / 1_000_000_000.0 * perSecond);
            refilledAt = now;
            if (tokens < 1) {
                return false;
            }
            tokens -= 1;
            return true;
        }
    }
}

