package com.dss26.payments.gateway.events;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.concurrent.CompletableFuture;

import org.apache.avro.generic.GenericRecord;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.errors.TimeoutException;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.SendResult;

import com.dss26.payments.gateway.GatewayProperties;
import com.dss26.payments.gateway.api.AuthorisationRequest;
import com.dss26.payments.gateway.api.Channel;

class AuthorisationEventPublisherTest {

    @SuppressWarnings("unchecked")
    private final KafkaTemplate<String, GenericRecord> kafka = mock(KafkaTemplate.class);

    private final AuthorisationEventPublisher publisher = new AuthorisationEventPublisher(kafka,
            new GatewayProperties("cards.authorisation.requested.v1", Duration.ofSeconds(2), Duration.ofHours(24),
                    "prod", new GatewayProperties.RateLimit(200, 400)));

    private final GenericRecord event = new CardAuthEventMapper(CardAuthSchema.load(), "prod").toEvent(
            "9a3e51c4-7b20-4f8d-8c61-2d4f0b7e9a13",
            new AuthorisationRequest("mch_lumen_coffee", "tok_4410982", new BigDecimal("42.50"), "EUR", "FR",
                    List.of(), Channel.ECOM),
            Instant.parse("2026-01-14T10:00:00Z"));

    @Test
    @SuppressWarnings("unchecked")
    void publishesKeyedByCardTokenWithTheRequestIdHeader() {
        when(kafka.send(any(ProducerRecord.class))).thenReturn(CompletableFuture.completedFuture(null));

        publisher.publish("tok_4410982", event, "req-20260114-0042");

        ArgumentCaptor<ProducerRecord<String, GenericRecord>> sent = ArgumentCaptor.forClass(ProducerRecord.class);
        verify(kafka).send(sent.capture());
        assertThat(sent.getValue().topic()).isEqualTo("cards.authorisation.requested.v1");
        assertThat(sent.getValue().key()).isEqualTo("tok_4410982");
        assertThat(sent.getValue().headers().lastHeader("x-request-id").value())
                .isEqualTo("req-20260114-0042".getBytes(StandardCharsets.UTF_8));
    }

    @Test
    @SuppressWarnings("unchecked")
    void sendsNoRequestIdHeaderWhenThereIsNone() {
        when(kafka.send(any(ProducerRecord.class))).thenReturn(CompletableFuture.completedFuture(null));

        publisher.publish("tok_4410982", event, null);

        ArgumentCaptor<ProducerRecord<String, GenericRecord>> sent = ArgumentCaptor.forClass(ProducerRecord.class);
        verify(kafka).send(sent.capture());
        assertThat(sent.getValue().headers().lastHeader("x-request-id")).isNull();
    }

    @Test
    @SuppressWarnings("unchecked")
    void aFailedSendBecomesPublishFailed() {
        when(kafka.send(any(ProducerRecord.class))).thenReturn(
                CompletableFuture.<SendResult<String, GenericRecord>>failedFuture(new TimeoutException("no ack")));

        assertThatThrownBy(() -> publisher.publish("tok_4410982", event, null))
                .isInstanceOf(PublishFailedException.class);
    }
}

package com.dss26.payments.gateway.events;

import static org.assertj.core.api.Assertions.assertThat;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

import org.apache.avro.Schema;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericRecord;
import org.junit.jupiter.api.Test;

import com.dss26.payments.gateway.api.AuthorisationRequest;
import com.dss26.payments.gateway.api.Channel;

class CardAuthEventMapperTest {

    private static final String AUTH_ID = "3f6c2a8e-5d1b-4c7e-9a40-1e8b7d2c6f05";
    private static final Instant RECEIVED_AT = Instant.parse("2022-03-14T09:15:30.123Z");

    private final Schema schema = CardAuthSchema.load();
    private final CardAuthEventMapper mapper = new CardAuthEventMapper(schema, "prod");

    @Test
    void loadsTheCardAuthEventSchemaFromTheClasspath() {
        assertThat(schema.getFullName()).isEqualTo("com.dss26.payments.CardAuthEvent");
    }

    @Test
    void mapsAnAcceptedRequestOntoTheEvent() {
        GenericRecord event = mapper.toEvent(AUTH_ID, request(), RECEIVED_AT);

        assertThat(event.get("auth_id")).isEqualTo(AUTH_ID);
        assertThat(event.get("card_token")).isEqualTo("tok_4410982");
        assertThat(event.get("merchant_id")).isEqualTo("mch_lumen_coffee");
        assertThat(event.get("amount")).isEqualTo("42.50");
        assertThat(event.get("currency")).isEqualTo("EUR");
        assertThat(event.get("ts")).isEqualTo(RECEIVED_AT.toEpochMilli());
        assertThat(event.get("risk_signals")).isEqualTo(List.of("VELOCITY_OK"));
        assertThat(event.get("channel")).isEqualTo("CARD_PRESENT");
        assertThat(event.get("tier")).isEqualTo("prod");
    }

    @Test
    void keepsEveryDecimalPlaceOfTheAmount() {
        AuthorisationRequest dinar = new AuthorisationRequest("mch_halcyon_retail", "tok_7730215",
                new BigDecimal("1250.375"), "KWD", "KW", List.of(), Channel.ECOM);

        assertThat(mapper.toEvent(AUTH_ID, dinar, RECEIVED_AT).get("amount")).isEqualTo("1250.375");
    }

    @Test
    void channelDefaultsToEcom() {
        AuthorisationRequest noChannel = new AuthorisationRequest("mch_lumen_coffee", "tok_4410982",
                new BigDecimal("9.99"), "EUR", "FR", List.of(), null);

        assertThat(mapper.toEvent(AUTH_ID, noChannel, RECEIVED_AT).get("channel")).isEqualTo("ECOM");
    }

    @Test
    void eventValidatesAgainstTheSchema() {
        assertThat(GenericData.get().validate(schema, mapper.toEvent(AUTH_ID, request(), RECEIVED_AT))).isTrue();
    }

    private static AuthorisationRequest request() {
        return new AuthorisationRequest(
                "mch_lumen_coffee",
                "tok_4410982",
                new BigDecimal("42.50"),
                "EUR",
                "FR",
                List.of("VELOCITY_OK"),
                Channel.CARD_PRESENT);
    }
}

package com.dss26.payments.gateway.idempotency;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

import org.junit.jupiter.api.Test;

import com.dss26.payments.gateway.api.AuthorisationRejectedException;

class IdempotencyStoreTest {

    private final MutableClock clock = new MutableClock(Instant.parse("2023-11-06T10:00:00Z"));
    private final IdempotencyStore store = new IdempotencyStore(Duration.ofHours(24), clock);

    @Test
    void firstUseReservesTheKey() {
        assertThat(store.reserve("key-1", "request-a", "auth-1")).isEmpty();
    }

    @Test
    void replayOfTheSameRequestReturnsTheFirstAuthId() {
        store.reserve("key-1", "request-a", "auth-1");

        assertThat(store.reserve("key-1", "request-a", "auth-2")).contains("auth-1");
    }

    @Test
    void sameKeyWithADifferentRequestIsAConflict() {
        store.reserve("key-1", "request-a", "auth-1");

        assertThatThrownBy(() -> store.reserve("key-1", "request-b", "auth-2"))
                .isInstanceOf(AuthorisationRejectedException.class)
                .hasMessageContaining("key-1");
    }

    @Test
    void keysExpireAfterTheTtl() {
        store.reserve("key-1", "request-a", "auth-1");
        clock.advance(Duration.ofHours(25));

        assertThat(store.reserve("key-1", "request-b", "auth-2")).isEmpty();
    }

    private static final class MutableClock extends Clock {

        private Instant now;

        private MutableClock(Instant now) {
            this.now = now;
        }

        void advance(Duration by) {
            now = now.plus(by);
        }

        @Override
        public ZoneId getZone() {
            return ZoneOffset.UTC;
        }

        @Override
        public Clock withZone(ZoneId zone) {
            return this;
        }

        @Override
        public Instant instant() {
            return now;
        }
    }
}

package com.dss26.payments.gateway.policy;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigDecimal;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;

import com.dss26.payments.gateway.api.AuthorisationRejectedException;
import com.dss26.payments.gateway.api.AuthorisationRequest;
import com.dss26.payments.gateway.api.Channel;

class AuthorisationPolicyTest {

    private final AuthorisationPolicy policy = new AuthorisationPolicy();

    @Test
    void acceptsAmountsWithinTheCurrencyMinorUnit() {
        assertThatCode(() -> policy.check(request("42.50", "EUR"))).doesNotThrowAnyException();
        assertThatCode(() -> policy.check(request("1500", "JPY"))).doesNotThrowAnyException();
        assertThatCode(() -> policy.check(request("1250.375", "KWD"))).doesNotThrowAnyException();
    }

    @Test
    void trailingZerosDoNotCountAsDecimalPlaces() {
        assertThatCode(() -> policy.check(request("1500.00", "JPY"))).doesNotThrowAnyException();
        assertThatCode(() -> policy.check(request("10.500", "EUR"))).doesNotThrowAnyException();
    }

    @Test
    void rejectsMoreDecimalPlacesThanTheCurrencyAllows() {
        assertThatThrownBy(() -> policy.check(request("1500.5", "JPY")))
                .isInstanceOfSatisfying(AuthorisationRejectedException.class, e -> {
                    assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                    assertThat(e.code()).isEqualTo("invalid_amount_scale");
                });
        assertThatThrownBy(() -> policy.check(request("42.505", "EUR")))
                .isInstanceOf(AuthorisationRejectedException.class);
    }

    @Test
    void rejectsCodesThatAreNotIso4217CurrenciesWith422() {
        assertThatThrownBy(() -> policy.check(request("10.00", "ZZZ")))
                .isInstanceOfSatisfying(AuthorisationRejectedException.class, e -> {
                    assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                    assertThat(e.code()).isEqualTo("unsupported_currency");
                });
    }

    private static AuthorisationRequest request(String amount, String currency) {
        return new AuthorisationRequest("mch_lumen_coffee", "tok_4410982", new BigDecimal(amount), currency, "FR",
                List.of(), Channel.ECOM);
    }
}

package com.dss26.payments.gateway.policy;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.atomic.AtomicLong;

import org.junit.jupiter.api.Test;

class MerchantRateLimiterTest {

    private final AtomicLong nanos = new AtomicLong();
    private final MerchantRateLimiter limiter = new MerchantRateLimiter(10, 20, nanos::get);

    @Test
    void allowsABurstThenRefuses() {
        for (int i = 0; i < 20; i++) {
            assertThat(limiter.tryAcquire("mch_lumen_coffee")).as("request %d", i).isTrue();
        }
        assertThat(limiter.tryAcquire("mch_lumen_coffee")).isFalse();
    }

    @Test
    void refillsAtTheConfiguredRate() {
        for (int i = 0; i < 20; i++) {
            limiter.tryAcquire("mch_lumen_coffee");
        }
        nanos.addAndGet(500_000_000L);

        for (int i = 0; i < 5; i++) {
            assertThat(limiter.tryAcquire("mch_lumen_coffee")).isTrue();
        }
        assertThat(limiter.tryAcquire("mch_lumen_coffee")).isFalse();
    }

    @Test
    void merchantsHaveSeparateBuckets() {
        for (int i = 0; i < 20; i++) {
            limiter.tryAcquire("mch_lumen_coffee");
        }

        assertThat(limiter.tryAcquire("mch_lumen_coffee")).isFalse();
        assertThat(limiter.tryAcquire("mch_halcyon_retail")).isTrue();
    }
}

