package com.dss26.payments.analytics;

import com.dss26.payments.CardAuthEvent;

import java.util.HashMap;
import java.util.Map;

/** Pure aggregation logic, kept out of the topology so it can be tested without Kafka. */
public final class KpiAggregator {

    private KpiAggregator() {
    }

    public static MerchantKpi empty() {
        return MerchantKpi.newBuilder()
                .setAuthCount(0L)
                .setAmountByCurrency(new HashMap<>())
                .setMaxAmount(0.0)
                .setChannelCounts(new HashMap<>())
                .setRiskFlaggedCount(0L)
                .build();
    }

    public static MerchantKpi add(MerchantKpi kpi, CardAuthEvent auth) {
        Map<String, Double> amounts = new HashMap<>(kpi.getAmountByCurrency());
        amounts.merge(auth.getCurrency(), auth.getAmount(), Double::sum);

        Map<String, Long> channels = new HashMap<>(kpi.getChannelCounts());
        channels.merge(auth.getChannel(), 1L, Long::sum);

        boolean flagged = auth.getRiskSignals() != null && !auth.getRiskSignals().isEmpty();

        return MerchantKpi.newBuilder(kpi)
                .setAuthCount(kpi.getAuthCount() + 1)
                .setAmountByCurrency(amounts)
                .setMaxAmount(Math.max(kpi.getMaxAmount(), auth.getAmount()))
                .setChannelCounts(channels)
                .setRiskFlaggedCount(kpi.getRiskFlaggedCount() + (flagged ? 1 : 0))
                .build();
    }

    /** Average ticket for one currency, 0 when the merchant took none in that currency. */
    public static double averageTicket(MerchantKpi kpi, String currency, long countInCurrency) {
        Double total = kpi.getAmountByCurrency().get(currency);
        if (total == null || countInCurrency == 0) {
            return 0.0;
        }
        return total / countInCurrency;
    }
}

package com.dss26.payments.analytics;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.KafkaStreams;
import org.apache.kafka.streams.KeyQueryMetadata;
import org.apache.kafka.streams.StoreQueryParameters;
import org.apache.kafka.streams.state.QueryableStoreTypes;
import org.apache.kafka.streams.state.ReadOnlyWindowStore;
import org.apache.kafka.streams.state.WindowStoreIterator;

import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * GET /merchants/{merchantId}/kpis?window=5m|1h&hours=N
 *
 * Interactive queries for the merchant portal BFF. A merchant's windows live
 * on one instance; any other instance answers with a 307 to the owner.
 */
public final class KpiQueryServer {

    record KpiView(String windowStart, long authCount, Map<String, Double> amountByCurrency,
                   double maxAmount, Map<String, Long> channelCounts, long riskFlaggedCount) {
    }

    private final KafkaStreams streams;
    private final HttpServer server;
    private final String self;
    private final ObjectMapper json = new ObjectMapper();

    public KpiQueryServer(KafkaStreams streams, String applicationServer, int port) throws IOException {
        this.streams = streams;
        this.self = applicationServer;
        this.server = HttpServer.create(new InetSocketAddress(port), 0);
        this.server.createContext("/merchants/", this::handle);
        this.server.createContext("/health", ex -> respond(ex, streams.state().isRunningOrRebalancing() ? 200 : 503, "{}"));
    }

    public void start() {
        server.start();
    }

    public void stop() {
        server.stop(1);
    }

    private void handle(HttpExchange ex) throws IOException {
        String[] parts = ex.getRequestURI().getPath().split("/");
        if (parts.length != 4 || !"kpis".equals(parts[3])) {
            respond(ex, 404, "{\"error\":\"not found\"}");
            return;
        }
        String merchantId = parts[2];
        Map<String, String> query = Query.parse(ex.getRequestURI().getRawQuery());
        String store = "1h".equals(query.get("window")) ? MerchantKpiTopology.STORE_1H : MerchantKpiTopology.STORE_5M;
        long hours = Math.min(Long.parseLong(query.getOrDefault("hours", "24")), 168);

        KeyQueryMetadata owner = streams.queryMetadataForKey(store, merchantId, Serdes.String().serializer());
        String ownerHost = owner.activeHost().host() + ":" + owner.activeHost().port();
        if (!ownerHost.equals(self)) {
            ex.getResponseHeaders().add("Location", "http://" + ownerHost + ex.getRequestURI());
            respond(ex, 307, "");
            return;
        }

        ReadOnlyWindowStore<String, MerchantKpi> windows = streams.store(
                StoreQueryParameters.fromNameAndType(store, QueryableStoreTypes.windowStore()));
        Instant to = Instant.now();
        List<KpiView> views = new ArrayList<>();
        try (WindowStoreIterator<MerchantKpi> it = windows.fetch(merchantId, to.minus(Duration.ofHours(hours)), to)) {
            it.forEachRemaining(kv -> views.add(new KpiView(Instant.ofEpochMilli(kv.key).toString(), kv.value.getAuthCount(),
                    kv.value.getAmountByCurrency(), kv.value.getMaxAmount(), kv.value.getChannelCounts(),
                    kv.value.getRiskFlaggedCount())));
        }
        respond(ex, 200, json.writeValueAsString(views));
    }

    private static void respond(HttpExchange ex, int status, String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(status, bytes.length == 0 ? -1 : bytes.length);
        try (OutputStream out = ex.getResponseBody()) {
            out.write(bytes);
        }
    }

    private static final class Query {
        static Map<String, String> parse(String raw) {
            Map<String, String> out = new java.util.HashMap<>();
            if (raw == null || raw.isEmpty()) {
                return out;
            }
            for (String pair : raw.split("&")) {
                int eq = pair.indexOf('=');
                if (eq > 0) {
                    out.put(pair.substring(0, eq), java.net.URLDecoder.decode(pair.substring(eq + 1), StandardCharsets.UTF_8));
                }
            }
            return out;
        }
    }
}

package com.dss26.payments.analytics;

import com.dss26.payments.CardAuthEvent;
import io.confluent.kafka.serializers.AbstractKafkaSchemaSerDeConfig;
import io.confluent.kafka.streams.serdes.avro.SpecificAvroSerde;
import org.apache.kafka.streams.KafkaStreams;
import org.apache.kafka.streams.StreamsConfig;
import org.apache.kafka.streams.Topology;
import org.apache.kafka.streams.errors.StreamsUncaughtExceptionHandler.StreamThreadExceptionResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

public final class MerchantAnalyticsApp {

    private static final Logger log = LoggerFactory.getLogger(MerchantAnalyticsApp.class);

    private MerchantAnalyticsApp() {
    }

    public static void main(String[] args) throws Exception {
        Properties props = StreamsConfigFactory.fromEnv(System.getenv());

        Map<String, Object> serdeConfig = new HashMap<>();
        props.stringPropertyNames().forEach(name -> serdeConfig.put(name, props.getProperty(name)));
        serdeConfig.put(AbstractKafkaSchemaSerDeConfig.SCHEMA_REGISTRY_URL_CONFIG,
                props.getProperty(AbstractKafkaSchemaSerDeConfig.SCHEMA_REGISTRY_URL_CONFIG));

        SpecificAvroSerde<CardAuthEvent> authSerde = new SpecificAvroSerde<>();
        authSerde.configure(serdeConfig, false);
        SpecificAvroSerde<MerchantKpi> kpiSerde = new SpecificAvroSerde<>();
        kpiSerde.configure(serdeConfig, false);

        Topology topology = MerchantKpiTopology.build(authSerde, kpiSerde);
        log.info("Topology:\n{}", topology.describe());

        KafkaStreams streams = new KafkaStreams(topology, props);
        streams.setUncaughtExceptionHandler(e -> {
            log.error("Stream thread died, replacing it", e);
            return StreamThreadExceptionResponse.REPLACE_THREAD;
        });

        String appServer = props.getProperty(StreamsConfig.APPLICATION_SERVER_CONFIG);
        int port = Integer.parseInt(appServer.substring(appServer.lastIndexOf(':') + 1));
        KpiQueryServer queries = new KpiQueryServer(streams, appServer, port);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            queries.stop();
            streams.close(Duration.ofSeconds(30));
        }, "shutdown"));

        streams.start();
        queries.start();
    }
}

package com.dss26.payments.analytics;

import com.dss26.payments.CardAuthEvent;
import org.apache.kafka.common.serialization.Serde;
import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.common.utils.Bytes;
import org.apache.kafka.streams.StreamsBuilder;
import org.apache.kafka.streams.Topology;
import org.apache.kafka.streams.kstream.Consumed;
import org.apache.kafka.streams.kstream.Grouped;
import org.apache.kafka.streams.kstream.KGroupedStream;
import org.apache.kafka.streams.kstream.Materialized;
import org.apache.kafka.streams.kstream.Named;
import org.apache.kafka.streams.kstream.TimeWindows;
import org.apache.kafka.streams.state.WindowStore;

import java.time.Duration;

/**
 * cards.authorisation.requested.v1 -> re-key by merchant -> tumbling windows.
 *
 * Processor and store names are fixed with Named/Materialized: renaming one
 * changes the internal topic names and needs an application reset (see README).
 */
public final class MerchantKpiTopology {

    public static final String INPUT_TOPIC = "cards.authorisation.requested.v1";
    public static final String STORE_5M = "merchant-kpi-5m";
    public static final String STORE_1H = "merchant-kpi-1h";

    static final Duration GRACE = Duration.ofMinutes(2);
    static final Duration RETENTION = Duration.ofDays(8);

    private MerchantKpiTopology() {
    }

    public static Topology build(Serde<CardAuthEvent> authSerde, Serde<MerchantKpi> kpiSerde) {
        StreamsBuilder builder = new StreamsBuilder();

        KGroupedStream<String, CardAuthEvent> byMerchant = builder
                .stream(INPUT_TOPIC, Consumed.with(Serdes.String(), authSerde).withName("authorisations"))
                .filter((key, auth) -> auth != null && "prod".equals(auth.getTier()), Named.as("prod-tier-only"))
                .selectKey((key, auth) -> auth.getMerchantId(), Named.as("key-by-merchant"))
                .groupByKey(Grouped.with("by-merchant", Serdes.String(), authSerde));

        windowed(byMerchant, Duration.ofMinutes(5), STORE_5M, kpiSerde);
        windowed(byMerchant, Duration.ofHours(1), STORE_1H, kpiSerde);

        return builder.build();
    }

    private static void windowed(KGroupedStream<String, CardAuthEvent> byMerchant, Duration size,
                                 String store, Serde<MerchantKpi> kpiSerde) {
        byMerchant
                .windowedBy(TimeWindows.ofSizeAndGrace(size, GRACE))
                .aggregate(
                        KpiAggregator::empty,
                        (merchantId, auth, kpi) -> KpiAggregator.add(kpi, auth),
                        Named.as(store + "-aggregate"),
                        Materialized.<String, MerchantKpi, WindowStore<Bytes, byte[]>>as(store)
                                .withKeySerde(Serdes.String())
                                .withValueSerde(kpiSerde)
                                .withRetention(RETENTION));
    }
}

package com.dss26.payments.analytics;

import io.confluent.kafka.serializers.AbstractKafkaSchemaSerDeConfig;
import org.apache.kafka.clients.CommonClientConfigs;
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.common.config.SaslConfigs;
import org.apache.kafka.streams.StreamsConfig;
import org.apache.kafka.streams.errors.LogAndContinueExceptionHandler;

import java.util.Map;
import java.util.Properties;

/** Builds the Streams configuration from the pod environment (see deploy/values-prod.yaml). */
public final class StreamsConfigFactory {

    public static final String APPLICATION_ID = "merchant-analytics-stream";

    private StreamsConfigFactory() {
    }

    public static Properties fromEnv(Map<String, String> env) {
        Properties p = new Properties();
        p.put(StreamsConfig.APPLICATION_ID_CONFIG, APPLICATION_ID);
        p.put(StreamsConfig.CLIENT_ID_CONFIG, APPLICATION_ID + "-" + env.getOrDefault("HOSTNAME", "local"));
        p.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, required(env, "KAFKA_BOOTSTRAP_SERVERS"));
        p.put(StreamsConfig.PROCESSING_GUARANTEE_CONFIG, StreamsConfig.EXACTLY_ONCE_V2);
        p.put(StreamsConfig.COMMIT_INTERVAL_MS_CONFIG, 1000);
        p.put(StreamsConfig.NUM_STREAM_THREADS_CONFIG, Integer.parseInt(env.getOrDefault("NUM_STREAM_THREADS", "2")));
        p.put(StreamsConfig.NUM_STANDBY_REPLICAS_CONFIG, 1);
        p.put(StreamsConfig.REPLICATION_FACTOR_CONFIG, 3);
        p.put(StreamsConfig.STATE_DIR_CONFIG, env.getOrDefault("STATE_DIR", "/var/lib/merchant-analytics-stream"));
        p.put(StreamsConfig.STATESTORE_CACHE_MAX_BYTES_CONFIG, 64L * 1024 * 1024);
        p.put(StreamsConfig.APPLICATION_SERVER_CONFIG, env.getOrDefault("APPLICATION_SERVER", "localhost:8080"));
        // A record we cannot read is logged and skipped: KPIs are statistics,
        // not a ledger, and must not stop for one bad payload.
        p.put(StreamsConfig.DEFAULT_DESERIALIZATION_EXCEPTION_HANDLER_CLASS_CONFIG,
                LogAndContinueExceptionHandler.class);
        p.put(StreamsConfig.consumerPrefix(ConsumerConfig.MAX_POLL_RECORDS_CONFIG), 1000);

        p.put(AbstractKafkaSchemaSerDeConfig.SCHEMA_REGISTRY_URL_CONFIG, required(env, "SCHEMA_REGISTRY_URL"));

        String protocol = env.getOrDefault("KAFKA_SECURITY_PROTOCOL", "SASL_SSL");
        p.put(CommonClientConfigs.SECURITY_PROTOCOL_CONFIG, protocol);
        if (protocol.startsWith("SASL")) {
            p.put(SaslConfigs.SASL_MECHANISM, "SCRAM-SHA-512");
            p.put(SaslConfigs.SASL_JAAS_CONFIG, String.format(
                    "org.apache.kafka.common.security.scram.ScramLoginModule required username=\"%s\" password=\"%s\";",
                    required(env, "KAFKA_USERNAME"), required(env, "KAFKA_PASSWORD")));
        }
        return p;
    }

    private static String required(Map<String, String> env, String name) {
        String value = env.get(name);
        if (value == null || value.isBlank()) {
            throw new IllegalStateException(name + " is not set");
        }
        return value;
    }
}

