package com.dss26.cards.disputes.chargeback;

public enum CardNetwork {
    VISA,
    MASTERCARD
}

package com.dss26.cards.disputes.chargeback;

import com.dss26.cards.events.ChargebackCategory;
import com.dss26.cards.events.ChargebackOutcome;

import java.math.BigDecimal;
import java.time.Instant;

public record Chargeback(
        String id,
        String authId,
        String merchantId,
        CardNetwork network,
        BigDecimal disputedAmount,
        String currency,
        String reasonCode,
        ChargebackCategory category,
        Instant openedAt,
        ChargebackOutcome outcome,
        BigDecimal recoveredAmount,
        Instant resolvedAt) {

    public boolean isOpen() {
        return outcome == null;
    }
}

package com.dss26.cards.disputes.chargeback;

import com.dss26.cards.events.ChargebackOpened;
import com.dss26.cards.events.ChargebackResolved;
import org.apache.avro.specific.SpecificRecord;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;

import java.math.BigDecimal;
import java.time.Duration;

/**
 * Publishes after the database commit, keyed by chargeback id. The key is also
 * the Elasticsearch document id (sink-elastic-disputes-search runs with
 * key.ignore=false), so an update replaces the document instead of adding one.
 */
@Component
public class ChargebackEventPublisher {

    static final String OPENED_TOPIC = "cards.chargeback.opened.v1";
    static final String RESOLVED_TOPIC = "cards.chargeback.resolved.v1";

    private final KafkaTemplate<String, SpecificRecord> kafka;

    public ChargebackEventPublisher(KafkaTemplate<String, SpecificRecord> kafka) {
        this.kafka = kafka;
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void on(ChargebackService.Opened event) {
        Chargeback cb = event.chargeback();
        kafka.send(OPENED_TOPIC, cb.id(), ChargebackOpened.newBuilder()
                .setChargebackId(cb.id())
                .setAuthId(cb.authId())
                .setMerchantId(cb.merchantId())
                .setDisputedAmount(cb.disputedAmount().doubleValue())
                .setCurrency(cb.currency())
                .setReasonCode(cb.reasonCode())
                .setReasonCategory(cb.category())
                .setOpenedAt(cb.openedAt())
                .build());
    }

    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void on(ChargebackService.Resolved event) {
        Chargeback cb = event.chargeback();
        BigDecimal recovered = cb.recoveredAmount() == null ? BigDecimal.ZERO : cb.recoveredAmount();
        kafka.send(RESOLVED_TOPIC, cb.id(), ChargebackResolved.newBuilder()
                .setChargebackId(cb.id())
                .setOutcome(cb.outcome())
                .setRecoveredAmount(recovered.doubleValue())
                .setCurrency(cb.currency())
                .setResolutionDays((int) Duration.between(cb.openedAt(), cb.resolvedAt()).toDays())
                .setResolvedAt(cb.resolvedAt())
                .build());
    }
}

package com.dss26.cards.disputes.chargeback;

import com.dss26.cards.events.ChargebackCategory;
import com.dss26.cards.events.ChargebackOutcome;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

@Repository
public class ChargebackRepository {

    private final JdbcClient jdbc;

    public ChargebackRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(Chargeback cb) {
        jdbc.sql("""
                INSERT INTO chargeback (id, auth_id, merchant_id, network, disputed_amount, currency,
                                        reason_code, category, opened_at)
                VALUES (:id, :authId, :merchantId, :network, :amount, :currency, :reasonCode, :category, :openedAt)
                """)
                .param("id", cb.id())
                .param("authId", cb.authId())
                .param("merchantId", cb.merchantId())
                .param("network", cb.network().name())
                .param("amount", cb.disputedAmount())
                .param("currency", cb.currency())
                .param("reasonCode", cb.reasonCode())
                .param("category", cb.category().name())
                .param("openedAt", Timestamp.from(cb.openedAt()))
                .update();
    }

    public void resolve(String id, ChargebackOutcome outcome, BigDecimal recovered, Instant resolvedAt) {
        jdbc.sql("""
                UPDATE chargeback SET outcome = :outcome, recovered_amount = :recovered, resolved_at = :resolvedAt
                 WHERE id = :id AND outcome IS NULL
                """)
                .param("id", id)
                .param("outcome", outcome.name())
                .param("recovered", recovered)
                .param("resolvedAt", Timestamp.from(resolvedAt))
                .update();
    }

    public Optional<Chargeback> find(String id) {
        return jdbc.sql("SELECT * FROM chargeback WHERE id = :id")
                .param("id", id)
                .query((rs, n) -> new Chargeback(
                        rs.getString("id"),
                        rs.getString("auth_id"),
                        rs.getString("merchant_id"),
                        CardNetwork.valueOf(rs.getString("network")),
                        rs.getBigDecimal("disputed_amount"),
                        rs.getString("currency"),
                        rs.getString("reason_code"),
                        ChargebackCategory.valueOf(rs.getString("category")),
                        rs.getTimestamp("opened_at").toInstant(),
                        rs.getString("outcome") == null ? null : ChargebackOutcome.valueOf(rs.getString("outcome")),
                        rs.getBigDecimal("recovered_amount"),
                        rs.getTimestamp("resolved_at") == null ? null : rs.getTimestamp("resolved_at").toInstant()))
                .optional();
    }

    public List<String> openIds() {
        return jdbc.sql("SELECT id FROM chargeback WHERE outcome IS NULL ORDER BY opened_at")
                .query(String.class)
                .list();
    }
}

package com.dss26.cards.disputes.chargeback;

import com.dss26.cards.events.ChargebackCategory;
import com.dss26.cards.events.ChargebackOutcome;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.util.NoSuchElementException;
import java.util.UUID;

@Service
public class ChargebackService {

    public record Opened(Chargeback chargeback) {
    }

    public record Resolved(Chargeback chargeback) {
    }

    private final ChargebackRepository repository;
    private final ApplicationEventPublisher events;
    private final Clock clock;

    public ChargebackService(ChargebackRepository repository, ApplicationEventPublisher events, Clock clock) {
        this.repository = repository;
        this.events = events;
        this.clock = clock;
    }

    @Transactional
    public Chargeback open(String authId, String merchantId, CardNetwork network, BigDecimal amount,
                           String currency, String reasonCode) {
        ChargebackCategory category = ReasonCodes.categorise(network, reasonCode);
        Chargeback cb = new Chargeback(UUID.randomUUID().toString(), authId, merchantId, network, amount,
                currency, reasonCode, category, clock.instant(), null, null, null);
        repository.insert(cb);
        events.publishEvent(new Opened(cb));
        return cb;
    }

    @Transactional
    public Chargeback resolve(String id, ChargebackOutcome outcome, BigDecimal recovered) {
        Chargeback cb = repository.find(id).orElseThrow(() -> new NoSuchElementException(id));
        if (!cb.isOpen()) {
            return cb;
        }
        Instant now = clock.instant();
        repository.resolve(id, outcome, recovered, now);
        Chargeback resolved = repository.find(id).orElseThrow();
        events.publishEvent(new Resolved(resolved));
        return resolved;
    }
}

package com.dss26.cards.disputes.chargeback;

import io.micrometer.core.instrument.MeterRegistry;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import java.time.Clock;
import java.util.concurrent.atomic.AtomicInteger;

/** Exposes how many open cases are inside the representment warning window. */
@Component
public class DeadlineWatch {

    private final ChargebackRepository repository;
    private final Clock clock;
    private final AtomicInteger dueSoon;

    public DeadlineWatch(ChargebackRepository repository, Clock clock, MeterRegistry meters) {
        this.repository = repository;
        this.clock = clock;
        this.dueSoon = meters.gauge("disputes.chargebacks.due_soon", new AtomicInteger());
    }

    @Scheduled(cron = "0 */15 * * * *", zone = "Europe/Paris")
    public void refresh() {
        int count = 0;
        for (String id : repository.openIds()) {
            Chargeback cb = repository.find(id).orElse(null);
            if (cb != null && RepresentmentDeadlines.dueSoon(cb.network(), cb.openedAt(), clock.instant())) {
                count++;
            }
        }
        dueSoon.set(count);
    }
}

package com.dss26.cards.disputes.chargeback;

import com.dss26.cards.events.ChargebackCategory;

import java.util.Map;

/**
 * Network reason code -> the bucketed category published on
 * cards.chargeback.opened.v1.
 *
 * Visa uses the Visa Claims Resolution groups (10.x fraud, 11.x authorisation,
 * 12.x processing errors, 13.x consumer disputes). Mastercard codes are mapped
 * one by one; anything we do not know lands in OTHER and shows up on the
 * "unmapped reason codes" panel.
 */
public final class ReasonCodes {

    private static final Map<String, ChargebackCategory> MASTERCARD = Map.of(
            "4837", ChargebackCategory.FRAUD,             // No cardholder authorisation
            "4863", ChargebackCategory.FRAUD,             // Cardholder does not recognise
            "4871", ChargebackCategory.FRAUD,             // Chip liability shift
            "4808", ChargebackCategory.AUTHORISATION,     // Authorisation-related
            "4834", ChargebackCategory.PROCESSING_ERROR,  // Point-of-interaction error
            "4831", ChargebackCategory.PROCESSING_ERROR,  // Transaction amount differs
            "4853", ChargebackCategory.CONSUMER_DISPUTE,  // Cardholder dispute
            "4841", ChargebackCategory.CONSUMER_DISPUTE); // Cancelled recurring

    private ReasonCodes() {
    }

    public static ChargebackCategory categorise(CardNetwork network, String reasonCode) {
        if (reasonCode == null || reasonCode.isBlank()) {
            return ChargebackCategory.OTHER;
        }
        return switch (network) {
            case VISA -> visa(reasonCode.trim());
            case MASTERCARD -> MASTERCARD.getOrDefault(reasonCode.trim(), ChargebackCategory.OTHER);
        };
    }

    private static ChargebackCategory visa(String code) {
        String group = code.contains(".") ? code.substring(0, code.indexOf('.')) : code;
        return switch (group) {
            case "10" -> ChargebackCategory.FRAUD;
            case "11" -> ChargebackCategory.AUTHORISATION;
            case "12" -> ChargebackCategory.PROCESSING_ERROR;
            case "13" -> ChargebackCategory.CONSUMER_DISPUTE;
            default -> ChargebackCategory.OTHER;
        };
    }
}

package com.dss26.cards.disputes.chargeback;

import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;

/**
 * Days we have to respond to a chargeback before the network rules it in the
 * cardholder's favour: 30 for a Visa dispute response, 45 for a Mastercard
 * second presentment. Cases inside the warning window go to the top of the
 * analysts' queue.
 */
public final class RepresentmentDeadlines {

    static final Duration WARNING_WINDOW = Duration.ofDays(5);

    private RepresentmentDeadlines() {
    }

    public static LocalDate deadline(CardNetwork network, Instant openedAt) {
        LocalDate opened = openedAt.atZone(ZoneOffset.UTC).toLocalDate();
        return switch (network) {
            case VISA -> opened.plusDays(30);
            case MASTERCARD -> opened.plusDays(45);
        };
    }

    public static boolean dueSoon(CardNetwork network, Instant openedAt, Instant now) {
        Instant due = deadline(network, openedAt).atStartOfDay(ZoneOffset.UTC).toInstant();
        return !now.isAfter(due) && Duration.between(now, due).compareTo(WARNING_WINDOW) <= 0;
    }
}

