package com.dss26.cards.clearing.matching;

import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * Read-only view of the issuer authorisation log (replicated from the core
 * authorisation host into the clearing database). Candidates are approved
 * authorisations on the same card and merchant in the last 30 days that have
 * not been matched yet.
 */
@Repository
public class AuthorisationLog {

    private static final String CANDIDATES = """
            SELECT auth_id, card_token, merchant_id, amount, currency
              FROM issuer_auth_log
             WHERE card_token = :card AND merchant_id = :merchant
               AND approved AND authorised_at > now() - interval '30 days'
               AND auth_id NOT IN (SELECT auth_id FROM clearing_match)
             ORDER BY authorised_at DESC
             LIMIT 20
            """;

    private final NamedParameterJdbcTemplate jdbc;

    public AuthorisationLog(NamedParameterJdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<MatchScorer.Authorisation> candidates(String cardToken, String merchantId) {
        return jdbc.query(CANDIDATES,
                new MapSqlParameterSource("card", cardToken).addValue("merchant", merchantId),
                (rs, n) -> new MatchScorer.Authorisation(rs.getString("auth_id"), rs.getString("card_token"),
                        rs.getString("merchant_id"), rs.getBigDecimal("amount"), rs.getString("currency")));
    }
}

package com.dss26.cards.clearing.matching;

import com.dss26.cards.clearing.Topics;
import com.dss26.cards.events.ClearingMatched;
import com.dss26.cards.events.ClearingReceived;
import org.apache.avro.specific.SpecificRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.Clock;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

@Component
public class ClearingMatcher {

    private static final Logger log = LoggerFactory.getLogger(ClearingMatcher.class);

    record Candidate(MatchScorer.Authorisation auth, double score) {
    }

    private final AuthorisationLog authorisations;
    private final NamedParameterJdbcTemplate jdbc;
    private final KafkaTemplate<String, SpecificRecord> kafka;
    private final Clock clock;

    public ClearingMatcher(AuthorisationLog authorisations, NamedParameterJdbcTemplate jdbc,
                           KafkaTemplate<String, SpecificRecord> kafka, Clock clock) {
        this.authorisations = authorisations;
        this.jdbc = jdbc;
        this.kafka = kafka;
        this.clock = clock;
    }

    @Transactional
    @KafkaListener(id = "matcher", topics = Topics.CLEARING_RECEIVED, groupId = "clearing-settlement-matcher")
    public void onClearingReceived(ClearingReceived clearing) {
        MapSqlParameterSource id = new MapSqlParameterSource("id", clearing.getClearingId());
        List<String> mcc = jdbc.queryForList("SELECT mcc FROM clearing_record WHERE clearing_id = :id", id, String.class);
        MatchScorer.Presentment presentment = new MatchScorer.Presentment(clearing.getCardToken(),
                clearing.getMerchantId(), mcc.isEmpty() ? "" : mcc.get(0),
                BigDecimal.valueOf(clearing.getAmount()), clearing.getCurrency());

        Optional<Candidate> best = authorisations.candidates(clearing.getCardToken(), clearing.getMerchantId())
                .stream()
                .map(a -> new Candidate(a, MatchScorer.score(presentment, a)))
                .filter(c -> c.score() >= MatchScorer.MATCH_THRESHOLD)
                .max(Comparator.comparingDouble(Candidate::score));

        if (best.isEmpty()) {
            jdbc.update("UPDATE clearing_record SET status = 'UNMATCHED' WHERE clearing_id = :id", id);
            log.info("No authorisation for clearing {} - routed to exceptions", clearing.getClearingId());
            return;
        }

        MatchScorer.Authorisation auth = best.get().auth();
        double authAmount = auth.amount().doubleValue();
        jdbc.update("INSERT INTO clearing_match (clearing_id, auth_id, score) VALUES (:id, :auth, :score)",
                new MapSqlParameterSource("id", clearing.getClearingId())
                        .addValue("auth", auth.authId())
                        .addValue("score", best.get().score()));
        kafka.send(Topics.CLEARING_MATCHED, clearing.getClearingId(), ClearingMatched.newBuilder()
                .setClearingId(clearing.getClearingId())
                .setAuthId(auth.authId())
                .setAuthAmount(authAmount)
                .setClearingAmount(clearing.getAmount())
                .setAmountDelta(clearing.getAmount() - authAmount)
                .setMatchConfidence(best.get().score())
                .setMatchedAt(clock.instant())
                .build());
    }
}

package com.dss26.cards.clearing.matching;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Set;

/**
 * Scores how well a presentment matches a candidate authorisation from the
 * issuer authorisation log. Same card and merchant are prerequisites; the
 * score then reflects how far the cleared amount is from the authorised one.
 */
public final class MatchScorer {

    /** Hotels, car hire, restaurants and bars: final amount legitimately differs (tips, incidentals). */
    static final Set<String> TOLERANT_MCCS = Set.of("7011", "7512", "5812", "5813");
    static final BigDecimal DEFAULT_TOLERANCE = new BigDecimal("0.00");
    static final BigDecimal HOSPITALITY_TOLERANCE = new BigDecimal("0.15");
    public static final double MATCH_THRESHOLD = 0.8;

    public record Presentment(String cardToken, String merchantId, String mcc, BigDecimal amount, String currency) {
    }

    public record Authorisation(String authId, String cardToken, String merchantId, BigDecimal amount, String currency) {
    }

    private MatchScorer() {
    }

    public static double score(Presentment p, Authorisation a) {
        if (!p.cardToken().equals(a.cardToken()) || !p.merchantId().equals(a.merchantId())
                || !p.currency().equals(a.currency())) {
            return 0.0;
        }
        if (p.amount().compareTo(a.amount()) == 0) {
            return 1.0;
        }
        if (a.amount().signum() == 0) {
            return 0.0;
        }
        BigDecimal delta = p.amount().subtract(a.amount()).abs()
                .divide(a.amount(), 4, RoundingMode.HALF_UP);
        BigDecimal tolerance = TOLERANT_MCCS.contains(p.mcc()) ? HOSPITALITY_TOLERANCE : DEFAULT_TOLERANCE;
        if (delta.compareTo(tolerance) > 0) {
            return 0.0;
        }
        // Inside tolerance: 0.95 at a tiny delta down to 0.8 at the limit.
        return 0.95 - 0.15 * delta.doubleValue() / tolerance.doubleValue();
    }
}

