package com.dss26.cards.lifecycle

import org.springframework.boot.autoconfigure.SpringBootApplication
import org.springframework.boot.runApplication
import org.springframework.context.annotation.Bean
import org.springframework.scheduling.annotation.EnableScheduling
import java.time.Clock

@SpringBootApplication
@EnableScheduling
class CardLifecycleApplication {
    @Bean
    fun clock(): Clock = Clock.systemUTC()
}

fun main(args: Array<String>) {
    runApplication<CardLifecycleApplication>(*args)
}

package com.dss26.cards.lifecycle.api

import com.dss26.cards.events.ActivationChannel
import com.dss26.cards.events.BlockInitiator
import com.dss26.cards.events.BlockReason
import com.dss26.cards.events.CardFormFactor
import com.dss26.cards.events.ReplacementReason
import com.dss26.cards.lifecycle.card.Card
import com.dss26.cards.lifecycle.card.CardService
import jakarta.validation.Valid
import jakarta.validation.constraints.NotBlank
import jakarta.validation.constraints.Pattern
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/v1/cards")
class CardController(private val cards: CardService) {

    data class IssueRequest(
        @field:NotBlank val cardToken: String,
        @field:NotBlank val customerId: String,
        @field:NotBlank val productCode: String,
        val formFactor: CardFormFactor,
        @field:Pattern(regexp = "\\d{6}") val bin: String,
        @field:Pattern(regexp = "\\d{6}") val expiryYyyymm: String,
    )

    data class BlockRequest(val reason: BlockReason, val initiator: BlockInitiator = BlockInitiator.CUSTOMER)
    data class ActivateRequest(val channel: ActivationChannel)
    data class ReplaceRequest(@field:NotBlank val newCardToken: String, val reason: ReplacementReason,
                              @field:Pattern(regexp = "\\d{6}") val expiryYyyymm: String)

    @GetMapping("/{cardToken}")
    fun get(@PathVariable cardToken: String): ResponseEntity<Card> =
        cards.find(cardToken)?.let { ResponseEntity.ok(it) } ?: ResponseEntity.notFound().build()

    @PostMapping
    fun issue(@Valid @RequestBody req: IssueRequest): Card =
        cards.issue(req.cardToken, req.customerId, req.productCode, req.formFactor, req.bin, req.expiryYyyymm)

    @PostMapping("/{cardToken}/activation")
    fun activate(@PathVariable cardToken: String, @RequestBody req: ActivateRequest): Card =
        cards.activate(cardToken, req.channel)

    @PostMapping("/{cardToken}/block")
    fun block(@PathVariable cardToken: String, @RequestBody req: BlockRequest): Card =
        cards.block(cardToken, req.reason, req.initiator)

    @PostMapping("/{cardToken}/replacement")
    fun replace(@PathVariable cardToken: String, @Valid @RequestBody req: ReplaceRequest): Card =
        cards.replace(cardToken, req.newCardToken, req.reason, req.expiryYyyymm)
}

package com.dss26.cards.lifecycle.card

import com.dss26.cards.events.BlockReason
import com.dss26.cards.events.CardFormFactor

enum class CardState { ISSUED, ACTIVE, BLOCKED, REPLACED }

class IllegalCardTransition(from: CardState, action: String) :
    IllegalStateException("Cannot $action a card in state $from")

/**
 * The only place that decides which lifecycle transitions are legal. Every
 * transition emits exactly one cards.card.* event through the outbox.
 */
object CardStateMachine {

    /** Virtual and tokenised cards are usable as soon as they exist; plastic waits for activation. */
    fun initialState(formFactor: CardFormFactor): CardState =
        if (formFactor == CardFormFactor.PHYSICAL) CardState.ISSUED else CardState.ACTIVE

    fun activate(from: CardState): CardState = when (from) {
        CardState.ISSUED -> CardState.ACTIVE
        else -> throw IllegalCardTransition(from, "activate")
    }

    fun block(from: CardState): CardState = when (from) {
        CardState.ISSUED, CardState.ACTIVE -> CardState.BLOCKED
        CardState.BLOCKED -> CardState.BLOCKED
        CardState.REPLACED -> throw IllegalCardTransition(from, "block")
    }

    /** Only a customer freeze can be lifted; lost, stolen and fraud blocks end in a replacement. */
    fun unblock(from: CardState, reason: BlockReason): CardState = when {
        from == CardState.BLOCKED && reason == BlockReason.CUSTOMER_REQUEST -> CardState.ACTIVE
        else -> throw IllegalCardTransition(from, "unblock")
    }

    fun replace(from: CardState): CardState = when (from) {
        CardState.ACTIVE, CardState.BLOCKED -> CardState.REPLACED
        else -> throw IllegalCardTransition(from, "replace")
    }
}

package com.dss26.cards.lifecycle.events

import org.apache.avro.specific.SpecificRecord
import org.springframework.kafka.core.KafkaTemplate
import org.springframework.scheduling.annotation.Scheduled
import org.springframework.stereotype.Component
import org.springframework.transaction.annotation.Transactional
import java.util.concurrent.TimeUnit

/**
 * Drains the outbox in id order. Keyed by card token, so every event for one
 * card lands on the same partition in the order it happened.
 */
@Component
class OutboxPublisher(
    private val outbox: Outbox,
    private val kafka: KafkaTemplate<String, SpecificRecord>,
) {

    @Scheduled(fixedDelay = 200)
    @Transactional
    fun drain() {
        val batch = outbox.pending(limit = 500)
        if (batch.isEmpty()) return
        val sends = batch.map { kafka.send(it.topic, it.key, it.record) }
        sends.forEach { it.get(10, TimeUnit.SECONDS) }
        outbox.markPublished(batch.map { it.id })
    }
}

package com.dss26.cards.lifecycle.risk

import com.dss26.cards.events.BlockInitiator
import com.dss26.cards.events.BlockReason
import com.dss26.cards.lifecycle.card.CardService
import com.dss26.risk.events.LimitType
import com.dss26.risk.events.RiskLimitBreached
import org.slf4j.LoggerFactory
import org.springframework.kafka.annotation.KafkaListener
import org.springframework.stereotype.Component

/**
 * Auto-blocks a card when the risk engine reports a breach that warrants it.
 * Velocity breaches only alert the cardholder (cardholder-alerts); blocking on
 * them froze too many legitimate cards.
 */
@Component
class RiskLimitListener(private val cards: CardService) {
    private val log = LoggerFactory.getLogger(javaClass)

    @KafkaListener(id = "risk-limits", topics = ["risk.limit.breached.v1"], groupId = "card-lifecycle-svc")
    fun onRiskLimitBreached(breach: RiskLimitBreached) {
        if (breach.limitType !in AUTO_BLOCK) return
        log.info("Blocking {} after {} breach", breach.cardToken, breach.limitType)
        cards.block(breach.cardToken, BlockReason.FRAUD_SUSPECTED, BlockInitiator.SYSTEM)
    }

    companion object {
        val AUTO_BLOCK = setOf(LimitType.EXPOSURE, LimitType.MCC_RESTRICTED)
    }
}

