cmd/sanctions-screening/main.go.text:
package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/twmb/franz-go/pkg/kgo"
	"github.com/twmb/franz-go/pkg/sasl/scram"
	"github.com/twmb/franz-go/pkg/sr"

	"github.com/dss26-org/sanctions-screening-svc/internal/api"
	"github.com/dss26-org/sanctions-screening-svc/internal/events"
	"github.com/dss26-org/sanctions-screening-svc/internal/lists"
	"github.com/dss26-org/sanctions-screening-svc/internal/match"
)

const refreshEvery = 30 * time.Minute

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	store := &lists.Store{}
	httpClient := &http.Client{Timeout: 2 * time.Minute}
	if err := store.Refresh(ctx, httpClient); err != nil {
		slog.Error("initial list load failed - refusing to start", "err", err)
		os.Exit(1)
	}
	var matcher atomic.Pointer[match.Matcher]
	matcher.Store(match.NewMatcher(store.Entries(), 0.88))
	go func() {
		for range time.Tick(refreshEvery) {
			if err := store.Refresh(ctx, httpClient); err != nil {
				slog.Error("list refresh failed, keeping previous lists", "err", err, "loaded_at", store.LoadedAt())
				continue
			}
			matcher.Store(match.NewMatcher(store.Entries(), 0.88))
		}
	}()

	brokers := strings.Split(os.Getenv("KAFKA_BOOTSTRAP_SERVERS"), ",")
	auth := scram.Auth{User: os.Getenv("KAFKA_USERNAME"), Pass: os.Getenv("KAFKA_PASSWORD")}
	producer, err := kgo.NewClient(
		kgo.SeedBrokers(brokers...),
		kgo.SASL(auth.AsSha512Mechanism()),
		kgo.RequiredAcks(kgo.AllISRAcks()),
		kgo.ClientID("sanctions-screening-svc"),
	)
	if err != nil {
		slog.Error("kafka client", "err", err)
		os.Exit(1)
	}
	defer producer.Close()

	registry, err := sr.NewClient(sr.URLs(os.Getenv("SCHEMA_REGISTRY_URL")))
	if err != nil {
		slog.Error("schema registry client", "err", err)
		os.Exit(1)
	}
	publisher, err := events.NewPublisher(ctx, producer, registry)
	if err != nil {
		slog.Error("publisher", "err", err)
		os.Exit(1)
	}

	h := &api.Handler{
		Matcher:  matcher.Load,
		Lists:    []string{string(lists.OFACSDN), string(lists.UNConsolidated), string(lists.EU), string(lists.UKSanctions)},
		Recorder: publisher,
		NewID:    newID,
	}

	consumer, err := kgo.NewClient(
		kgo.SeedBrokers(brokers...),
		kgo.SASL(auth.AsSha512Mechanism()),
		kgo.ConsumerGroup("sanctions-screening-svc"),
		kgo.ConsumeTopics(events.ProfileUpdatedTopic),
		kgo.DisableAutoCommit(),
		kgo.ClientID("sanctions-screening-svc"),
	)
	if err != nil {
		slog.Error("kafka consumer", "err", err)
		os.Exit(1)
	}
	defer consumer.Close()
	rescreen := &events.Rescreen{
		Client:     consumer,
		Serde:      events.ProfileSerde(ctx, registry),
		ProfileURL: os.Getenv("CUSTOMER_PROFILE_URL"),
		Screen: func(_ context.Context, customerID, name string) error {
			hits := matcher.Load().Screen(name)
			resp := api.Response{ScreeningID: newID(), Outcome: "NO_HIT", Hits: hits}
			if len(hits) > 0 {
				resp.Outcome, resp.MatchScore = "POTENTIAL_MATCH", hits[0].Score
			}
			req := api.Request{CustomerID: customerID, Name: name, Trigger: "PERIODIC_REFRESH"}
			return publisher.Record(req, resp, h.Lists, time.Now())
		},
	}
	go func() {
		for ctx.Err() == nil {
			if err := rescreen.Run(ctx); err != nil && ctx.Err() == nil {
				slog.Error("rescreen loop stopped, restarting in 30s", "err", err)
				time.Sleep(30 * time.Second)
			}
		}
	}()

	srv := &http.Server{Addr: ":8080", Handler: h.Routes(), ReadHeaderTimeout: 5 * time.Second}
	go func() {
		<-ctx.Done()
		shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = srv.Shutdown(shutdown)
	}()
	slog.Info("listening", "addr", srv.Addr, "entries", len(store.Entries()))
	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		slog.Error("server", "err", err)
		os.Exit(1)
	}
}

func newID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

internal/api/handler.go.text:
// Package api serves synchronous screening for onboarding and payments.
package api

import (
	"encoding/json"
	"log/slog"
	"net/http"
	"time"

	"github.com/dss26-org/sanctions-screening-svc/internal/match"
)

// Trigger values mirror the SanctionsTrigger enum on sanctions.screening.completed.v1.
var triggers = map[string]bool{
	"ACCOUNT_OPEN": true, "PERIODIC_REFRESH": true, "CROSS_BORDER_TXN": true, "BENEFICIARY_ADDED": true,
}

type Request struct {
	CustomerID string `json:"customerId"`
	Name       string `json:"name"`
	Trigger    string `json:"trigger"`
}

type Response struct {
	ScreeningID string      `json:"screeningId"`
	Outcome     string      `json:"outcome"` // NO_HIT or POTENTIAL_MATCH; analysts confirm or clear later
	MatchScore  float64     `json:"matchScore"`
	Hits        []match.Hit `json:"hits,omitempty"`
}

// Recorder publishes the outcome; implemented by events.Publisher.
type Recorder interface {
	Record(r Request, resp Response, lists []string, at time.Time) error
}

type Handler struct {
	Matcher  func() *match.Matcher
	Lists    []string
	Recorder Recorder
	NewID    func() string
}

func (h *Handler) Routes() *http.ServeMux {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/screenings", h.screen)
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) { w.WriteHeader(http.StatusOK) })
	return mux
}

func (h *Handler) screen(w http.ResponseWriter, r *http.Request) {
	var req Request
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Name == "" || !triggers[req.Trigger] {
		http.Error(w, `{"error":"customerId, name and a valid trigger are required"}`, http.StatusBadRequest)
		return
	}
	hits := h.Matcher().Screen(req.Name)
	resp := Response{ScreeningID: h.NewID(), Outcome: "NO_HIT", Hits: hits}
	if len(hits) > 0 {
		resp.Outcome = "POTENTIAL_MATCH"
		resp.MatchScore = hits[0].Score
	}
	if err := h.Recorder.Record(req, resp, h.Lists, time.Now()); err != nil {
		// The caller gets the answer either way; the event is retried by the
		// producer, and a failure here must never let a payment through unscreened.
		slog.Error("recording screening failed", "screening_id", resp.ScreeningID, "err", err)
	}
	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(resp)
}

internal/events/profile_consumer.go.text:
package events

import (
	"context"
	_ "embed"
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"slices"

	"github.com/hamba/avro/v2"
	"github.com/twmb/franz-go/pkg/kgo"
	"github.com/twmb/franz-go/pkg/sr"
)

const ProfileUpdatedTopic = "customer.profile.updated.v1"

// Fields whose change means the customer must be screened again.
var screeningFields = []string{"first_name", "last_name", "date_of_birth", "nationality", "address"}

type profileUpdated struct {
	CustomerID    string   `avro:"customer_id"`
	ChangedFields []string `avro:"changed_fields"`
}

//go:embed schemas/customer.profile.updated.v1.avsc
var profileSchema string

// ProfileSerde decodes customer.profile.updated.v1 by the schema id on each record.
func ProfileSerde(ctx context.Context, registry *sr.Client) *sr.Serde {
	schema := avro.MustParse(profileSchema)
	var serde sr.Serde
	if subject, err := registry.SchemaByVersion(ctx, ProfileUpdatedTopic+"-value", -1); err == nil {
		serde.Register(subject.ID, profileUpdated{},
			sr.DecodeFn(func(b []byte, v any) error { return avro.Unmarshal(schema, b, v) }))
	}
	return &serde
}

// Rescreen consumes customer.profile.updated.v1 (group sanctions-screening-svc)
// and rescreens customers whose identifying data changed.
type Rescreen struct {
	Client     *kgo.Client
	Serde      *sr.Serde
	ProfileURL string
	Screen     func(ctx context.Context, customerID, name string) error
}

func (r *Rescreen) Run(ctx context.Context) error {
	for {
		fetches := r.Client.PollFetches(ctx)
		if fetches.IsClientClosed() || ctx.Err() != nil {
			return ctx.Err()
		}
		fetches.EachError(func(t string, p int32, err error) {
			slog.Error("fetch error", "topic", t, "partition", p, "err", err)
		})
		var failed error
		fetches.EachRecord(func(rec *kgo.Record) {
			if failed != nil {
				return
			}
			var ev profileUpdated
			if err := r.Serde.Decode(rec.Value, &ev); err != nil {
				failed = fmt.Errorf("decode %s/%d@%d: %w", rec.Topic, rec.Partition, rec.Offset, err)
				return
			}
			if !slices.ContainsFunc(ev.ChangedFields, func(f string) bool { return slices.Contains(screeningFields, f) }) {
				return
			}
			name, err := r.fullName(ctx, ev.CustomerID)
			if err == nil {
				err = r.Screen(ctx, ev.CustomerID, name)
			}
			if err != nil {
				failed = err
			}
		})
		if failed != nil {
			// Do not commit: the batch is retried after a pause.
			return failed
		}
		if err := r.Client.CommitUncommittedOffsets(ctx); err != nil {
			slog.Error("commit failed", "err", err)
		}
	}
}

func (r *Rescreen) fullName(ctx context.Context, customerID string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, r.ProfileURL+"/v1/customers/"+customerID, nil)
	if err != nil {
		return "", err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	var body struct {
		FirstName string `json:"firstName"`
		LastName  string `json:"lastName"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		return "", err
	}
	return body.FirstName + " " + body.LastName, nil
}

