package lists

import (
	"encoding/xml"
	"io"
	"strings"
)

// parseUN reads the UN Security Council consolidated list.
func parseUN(r io.Reader) ([]Entry, error) {
	var doc struct {
		Individuals []struct {
			Ref     string `xml:"REFERENCE_NUMBER"`
			First   string `xml:"FIRST_NAME"`
			Second  string `xml:"SECOND_NAME"`
			Third   string `xml:"THIRD_NAME"`
			Aliases []struct {
				Name string `xml:"ALIAS_NAME"`
			} `xml:"INDIVIDUAL_ALIAS"`
		} `xml:"INDIVIDUALS>INDIVIDUAL"`
		Entities []struct {
			Ref  string `xml:"REFERENCE_NUMBER"`
			Name string `xml:"FIRST_NAME"`
		} `xml:"ENTITIES>ENTITY"`
	}
	if err := xml.NewDecoder(r).Decode(&doc); err != nil {
		return nil, err
	}
	var out []Entry
	for _, i := range doc.Individuals {
		e := Entry{ID: "UN-" + i.Ref, List: UNConsolidated, Name: strings.Join(nonEmpty(i.First, i.Second, i.Third), " ")}
		for _, a := range i.Aliases {
			if a.Name != "" {
				e.Aliases = append(e.Aliases, a.Name)
			}
		}
		out = append(out, e)
	}
	for _, en := range doc.Entities {
		out = append(out, Entry{ID: "UN-" + en.Ref, List: UNConsolidated, Name: en.Name})
	}
	return out, nil
}

// parseEU reads the EU Financial Sanctions Files (FSF) full list.
func parseEU(r io.Reader) ([]Entry, error) {
	var doc struct {
		Entities []struct {
			LogicalID string `xml:"logicalId,attr"`
			Names     []struct {
				Whole string `xml:"wholeName,attr"`
			} `xml:"nameAlias"`
		} `xml:"sanctionEntity"`
	}
	if err := xml.NewDecoder(r).Decode(&doc); err != nil {
		return nil, err
	}
	out := make([]Entry, 0, len(doc.Entities))
	for _, s := range doc.Entities {
		if len(s.Names) == 0 {
			continue
		}
		e := Entry{ID: "EU-" + s.LogicalID, List: EU, Name: s.Names[0].Whole}
		for _, n := range s.Names[1:] {
			e.Aliases = append(e.Aliases, n.Whole)
		}
		out = append(out, e)
	}
	return out, nil
}

// parseUK reads the FCDO UK Sanctions List (the only UK source since OFSI
// closed its consolidated list on 28 January 2026).
func parseUK(r io.Reader) ([]Entry, error) {
	var doc struct {
		Designations []struct {
			UniqueID string `xml:"UniqueID"`
			Names    []struct {
				Name string `xml:"Name6"`
				Type string `xml:"NameType"`
			} `xml:"Names>Name"`
		} `xml:"Designation"`
	}
	if err := xml.NewDecoder(r).Decode(&doc); err != nil {
		return nil, err
	}
	var out []Entry
	for _, d := range doc.Designations {
		e := Entry{ID: "UK-" + d.UniqueID, List: UKSanctions}
		for _, n := range d.Names {
			if n.Type == "Primary Name" && e.Name == "" {
				e.Name = n.Name
			} else if n.Name != "" {
				e.Aliases = append(e.Aliases, n.Name)
			}
		}
		out = append(out, e)
	}
	return out, nil
}

func nonEmpty(parts ...string) []string {
	out := parts[:0]
	for _, p := range parts {
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

internal/match/jarowinkler.go.text:
package match

// JaroWinkler returns the Jaro-Winkler similarity of a and b in [0, 1].
func JaroWinkler(a, b string) float64 {
	ra, rb := []rune(a), []rune(b)
	if len(ra) == 0 && len(rb) == 0 {
		return 1
	}
	if len(ra) == 0 || len(rb) == 0 {
		return 0
	}
	window := max(len(ra), len(rb))/2 - 1
	if window < 0 {
		window = 0
	}
	matchedA := make([]bool, len(ra))
	matchedB := make([]bool, len(rb))
	matches := 0
	for i := range ra {
		lo, hi := max(0, i-window), min(len(rb), i+window+1)
		for j := lo; j < hi; j++ {
			if !matchedB[j] && ra[i] == rb[j] {
				matchedA[i], matchedB[j] = true, true
				matches++
				break
			}
		}
	}
	if matches == 0 {
		return 0
	}
	transpositions, k := 0, 0
	for i := range ra {
		if !matchedA[i] {
			continue
		}
		for !matchedB[k] {
			k++
		}
		if ra[i] != rb[k] {
			transpositions++
		}
		k++
	}
	m := float64(matches)
	jaro := (m/float64(len(ra)) + m/float64(len(rb)) + (m-float64(transpositions)/2)/m) / 3

	prefix := 0
	for prefix < min(4, len(ra), len(rb)) && ra[prefix] == rb[prefix] {
		prefix++
	}
	return jaro + float64(prefix)*0.1*(1-jaro)
}

internal/match/matcher.go.text:
package match

import (
	"sort"

	"github.com/dss26-org/sanctions-screening-svc/internal/lists"
)

// Hit is one list entry that scored at or above the review threshold.
type Hit struct {
	Entry lists.Entry
	Score float64
}

// Matcher compares names against every loaded list. It is safe for
// concurrent use once built; reloads swap in a new Matcher.
type Matcher struct {
	threshold float64
	entries   []indexed
}

type indexed struct {
	entry lists.Entry
	names []string // normalised primary name and aliases
}

// NewMatcher indexes entries. threshold is the score at which a hit goes to
// an analyst (0.88 since the 2021 calibration against the OFAC test set).
func NewMatcher(entries []lists.Entry, threshold float64) *Matcher {
	m := &Matcher{threshold: threshold, entries: make([]indexed, 0, len(entries))}
	for _, e := range entries {
		ix := indexed{entry: e}
		for _, n := range append([]string{e.Name}, e.Aliases...) {
			if nn := Normalize(n); nn != "" {
				ix.names = append(ix.names, nn)
			}
		}
		m.entries = append(m.entries, ix)
	}
	return m
}

// Screen returns every hit for name, best first.
func (m *Matcher) Screen(name string) []Hit {
	q := Normalize(name)
	if q == "" {
		return nil
	}
	var hits []Hit
	for _, ix := range m.entries {
		best := 0.0
		for _, n := range ix.names {
			if s := JaroWinkler(q, n); s > best {
				best = s
			}
		}
		if best >= m.threshold {
			hits = append(hits, Hit{Entry: ix.entry, Score: best})
		}
	}
	sort.Slice(hits, func(i, j int) bool { return hits[i].Score > hits[j].Score })
	return hits
}

internal/match/matcher_test.go.text:
package match

import (
	"testing"

	"github.com/dss26-org/sanctions-screening-svc/internal/lists"
)

func TestNormalizeFoldsDiacriticsAndHonorifics(t *testing.T) {
	cases := map[string]string{
		"Mr. José  Álvarez-Núñez": "jose alvarez nunez",
		"ACME TRADING LLC":        "acme trading",
		"  Dr Zoë O'Brien ":       "zoe o brien",
	}
	for in, want := range cases {
		if got := Normalize(in); got != want {
			t.Errorf("Normalize(%q) = %q, want %q", in, got, want)
		}
	}
}

func TestJaroWinklerKnownValues(t *testing.T) {
	if got := JaroWinkler("martha", "marhta"); got < 0.96 || got > 0.962 {
		t.Errorf("martha/marhta = %.4f, want ~0.961", got)
	}
	if got := JaroWinkler("abc", "xyz"); got != 0 {
		t.Errorf("abc/xyz = %.4f, want 0", got)
	}
}

func TestScreenFindsAliasWithTypo(t *testing.T) {
	m := NewMatcher([]lists.Entry{
		{ID: "EU-2022-0147", List: lists.EU, Name: "Ivan Petrovich Sidorov", Aliases: []string{"Ivan Sidorov"}},
		{ID: "OFAC-41022", List: lists.OFACSDN, Name: "Northern Star Shipping LLC"},
	}, 0.88)

	hits := m.Screen("Ivan Sidorow")
	if len(hits) != 1 || hits[0].Entry.ID != "EU-2022-0147" {
		t.Fatalf("hits = %+v, want EU-2022-0147", hits)
	}
	if got := m.Screen("Jane Smith"); len(got) != 0 {
		t.Fatalf("unexpected hits for an unrelated name: %+v", got)
	}
}

internal/match/normalize.go.text:
// Package match scores customer names against sanctions list entries.
package match

import (
	"strings"
	"unicode"

	"golang.org/x/text/runes"
	"golang.org/x/text/transform"
	"golang.org/x/text/unicode/norm"
)

// honorifics and legal-form words carry no identity and only add noise.
var noise = map[string]bool{
	"mr": true, "mrs": true, "ms": true, "dr": true, "sir": true,
	"ltd": true, "llc": true, "plc": true, "gmbh": true, "sa": true, "ooo": true, "jsc": true,
}

// Normalize folds case, strips diacritics and punctuation, drops honorifics
// and legal forms, and sorts nothing: token order matters for Jaro-Winkler,
// so callers compare token sets separately.
func Normalize(name string) string {
	t := transform.Chain(norm.NFD, runes.Remove(runes.In(unicode.Mn)), norm.NFC)
	folded, _, err := transform.String(t, name)
	if err != nil {
		folded = name
	}
	folded = strings.ToLower(folded)
	var b strings.Builder
	for _, r := range folded {
		switch {
		case unicode.IsLetter(r) || unicode.IsDigit(r):
			b.WriteRune(r)
		default:
			b.WriteRune(' ')
		}
	}
	tokens := make([]string, 0, 4)
	for _, tok := range strings.Fields(b.String()) {
		if !noise[tok] {
			tokens = append(tokens, tok)
		}
	}
	return strings.Join(tokens, " ")
}

