package com.dss26.customer.profile.api;

import com.dss26.customer.events.ConsentType;
import com.dss26.customer.profile.consent.ConsentService;
import com.dss26.customer.profile.gdpr.ErasureService;
import com.dss26.customer.profile.profile.Profile;
import com.dss26.customer.profile.profile.ProfileService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

@RestController
@RequestMapping("/v1/customers")
public class ProfileController {

    public record ConsentRequest(ConsentType type, String scope) {
    }

    private final ProfileService profiles;
    private final ConsentService consents;
    private final ErasureService erasure;

    public ProfileController(ProfileService profiles, ConsentService consents, ErasureService erasure) {
        this.profiles = profiles;
        this.consents = consents;
        this.erasure = erasure;
    }

    @GetMapping("/{customerId}")
    public ResponseEntity<Profile> get(@PathVariable String customerId) {
        return ResponseEntity.of(profiles.find(customerId));
    }

    /** Channels send X-Changed-By: CUSTOMER; the contact-centre desktop sends its operator id too. */
    @PutMapping("/{customerId}")
    public Profile update(@PathVariable String customerId, @RequestBody Profile profile,
                          @RequestHeader(value = "X-Changed-By", defaultValue = "CUSTOMER") String changedBy,
                          @RequestHeader(value = "X-Operator-Id", required = false) String operatorId) {
        return profiles.update(profile, changedBy, operatorId);
    }

    @PostMapping("/{customerId}/consents")
    public Map<String, String> grant(@PathVariable String customerId, @RequestBody ConsentRequest req) {
        return Map.of("consentId", consents.grant(customerId, req.type(), req.scope()));
    }

    @DeleteMapping("/{customerId}")
    public ResponseEntity<Void> erase(@PathVariable String customerId) {
        return erasure.erase(customerId) ? ResponseEntity.noContent().build() : ResponseEntity.status(409).build();
    }
}

package com.dss26.customer.profile.consent;

import com.dss26.customer.events.ConsentType;
import com.dss26.customer.profile.events.CustomerEvents;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.sql.Timestamp;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.UUID;

/**
 * Consents the customer gives: PSD2 access for third-party providers,
 * marketing channels, data sharing. Every grant is evidence for PSD2 and GDPR
 * audits, so it is stored and published, never updated in place.
 */
@Service
public class ConsentService {

    /** PSD2 RTS (as amended in 2023): account information access needs SCA again every 180 days. */
    static final Duration AISP_VALIDITY = Duration.ofDays(180);

    private final NamedParameterJdbcTemplate jdbc;
    private final CustomerEvents events;
    private final Clock clock = Clock.systemUTC();

    public ConsentService(NamedParameterJdbcTemplate jdbc, CustomerEvents events) {
        this.jdbc = jdbc;
        this.events = events;
    }

    @Transactional
    public String grant(String customerId, ConsentType type, String scope) {
        String consentId = UUID.randomUUID().toString();
        Instant expiresAt = type == ConsentType.PSD2_AISP ? clock.instant().plus(AISP_VALIDITY) : null;
        jdbc.update("""
                INSERT INTO customer_consent (consent_id, customer_id, consent_type, scope, granted_at, expires_at)
                VALUES (:id, :customer, :type, :scope, now(), :expiresAt)
                """, new MapSqlParameterSource()
                .addValue("id", consentId)
                .addValue("customer", customerId)
                .addValue("type", type.name())
                .addValue("scope", scope)
                .addValue("expiresAt", expiresAt == null ? null : Timestamp.from(expiresAt)));
        events.consentGranted(customerId, consentId, type, scope, expiresAt);
        return consentId;
    }
}

package com.dss26.customer.profile.events;

import com.dss26.customer.events.AccountOpened;
import com.dss26.customer.events.ChangedBy;
import com.dss26.customer.events.ConsentGranted;
import com.dss26.customer.events.ConsentType;
import com.dss26.customer.events.ProfileUpdated;
import org.apache.avro.specific.SpecificRecord;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.util.List;

/** customer.* events, keyed by customer id, sent after the surrounding transaction commits. */
@Component
public class CustomerEvents {

    static final String ACCOUNT_OPENED = "customer.account.opened.v1";
    static final String PROFILE_UPDATED = "customer.profile.updated.v1";
    static final String CONSENT_GRANTED = "customer.consent.granted.v1";

    private final KafkaTemplate<String, SpecificRecord> kafka;
    private final Clock clock;

    public CustomerEvents(KafkaTemplate<String, SpecificRecord> kafka) {
        this.kafka = kafka;
        this.clock = Clock.systemUTC();
    }

    public void profileUpdated(String customerId, List<String> changedFields, String changedBy, String agentId) {
        afterCommit(PROFILE_UPDATED, customerId, ProfileUpdated.newBuilder()
                .setCustomerId(customerId)
                .setChangedFields(changedFields)
                .setChangedBy(ChangedBy.valueOf(changedBy))
                .setAgentId(agentId)
                .setChangedAt(clock.instant())
                .build());
    }

    public void consentGranted(String customerId, String consentId, ConsentType type, String scope, Instant expiresAt) {
        afterCommit(CONSENT_GRANTED, customerId, ConsentGranted.newBuilder()
                .setCustomerId(customerId)
                .setConsentId(consentId)
                .setConsentType(type)
                .setScope(scope)
                .setExpiresAt(expiresAt)
                .setGrantedAt(clock.instant())
                .build());
    }

    public void accountOpened(String customerId, String accountNumber, String productCode, String kycReference,
                              String currency) {
        afterCommit(ACCOUNT_OPENED, customerId, AccountOpened.newBuilder()
                .setCustomerId(customerId)
                .setAccountNumber(accountNumber)
                .setProductCode(productCode)
                .setKycReference(kycReference)
                .setOpeningBalance(BigDecimal.ZERO.doubleValue())
                .setCurrency(currency)
                .setOpenedAt(clock.instant())
                .build());
    }

    private void afterCommit(String topic, String key, SpecificRecord value) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            kafka.send(topic, key, value);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                kafka.send(topic, key, value);
            }
        });
    }
}

package com.dss26.customer.profile.gdpr;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * GDPR article 17 erasure, after the retention periods that override it
 * (five years after the relationship ends for AML records, ten for
 * accounting). Personal fields are overwritten in place; the customer id
 * stays so ledger and audit references remain valid.
 */
@Service
public class ErasureService {

    private static final Logger log = LoggerFactory.getLogger(ErasureService.class);

    private final NamedParameterJdbcTemplate jdbc;

    public ErasureService(NamedParameterJdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Transactional
    public boolean erase(String customerId) {
        Boolean blocked = jdbc.queryForObject("""
                SELECT EXISTS (SELECT 1 FROM customer_account
                                WHERE customer_id = :id
                                  AND (closed_at IS NULL OR closed_at > now() - interval '5 years'))
                """, new MapSqlParameterSource("id", customerId), Boolean.class);
        if (Boolean.TRUE.equals(blocked)) {
            log.info("Erasure for {} deferred: retention period still running", customerId);
            return false;
        }
        jdbc.update("""
                UPDATE customer_profile
                   SET first_name = 'ERASED', last_name = 'ERASED', date_of_birth = NULL, nationality = NULL,
                       email = NULL, phone = NULL, address = NULL, erased_at = now()
                 WHERE customer_id = :id
                """, new MapSqlParameterSource("id", customerId));
        jdbc.update("DELETE FROM customer_consent WHERE customer_id = :id", new MapSqlParameterSource("id", customerId));
        return true;
    }
}

package com.dss26.customer.profile.onboarding;

import com.dss26.customer.profile.events.CustomerEvents;
import com.dss26.kyc.events.KycOutcome;
import com.dss26.kyc.events.KycVerificationCompleted;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.RestTemplate;

import java.util.Map;

/**
 * Opens the current account once KYC passes. The account number is allocated
 * by the core ledger through core-banking-adapter; the customer record already
 * exists from the application step.
 */
@Component
public class KycVerifiedListener {

    private static final Logger log = LoggerFactory.getLogger(KycVerifiedListener.class);

    private final NamedParameterJdbcTemplate jdbc;
    private final CustomerEvents events;
    private final RestTemplate core;

    public KycVerifiedListener(NamedParameterJdbcTemplate jdbc, CustomerEvents events, RestTemplateBuilder builder,
                               @Value("${customer.core-banking-url}") String coreBankingUrl) {
        this.jdbc = jdbc;
        this.events = events;
        this.core = builder.rootUri(coreBankingUrl).build();
    }

    @Transactional
    @KafkaListener(id = "kyc-verified", topics = "kyc.verification.completed.v1", groupId = "customer-profile-svc")
    public void onVerification(KycVerificationCompleted kyc) {
        if (kyc.getOutcome() != KycOutcome.PASS) {
            return;
        }
        Integer existing = jdbc.queryForObject(
                "SELECT count(*) FROM customer_account WHERE kyc_reference = :ref",
                new MapSqlParameterSource("ref", kyc.getKycReference()), Integer.class);
        if (existing != null && existing > 0) {
            log.info("Account for {} already opened, skipping redelivery", kyc.getKycReference());
            return;
        }
        @SuppressWarnings("unchecked")
        Map<String, String> opened = core.postForObject("/v1/accounts",
                Map.of("customerId", kyc.getCustomerId(), "productCode", "CURRENT_EUR"), Map.class);
        String accountNumber = opened.get("accountNumber");
        jdbc.update("""
                INSERT INTO customer_account (account_number, customer_id, product_code, kyc_reference, currency)
                VALUES (:account, :customer, 'CURRENT_EUR', :ref, 'EUR')
                """, new MapSqlParameterSource()
                .addValue("account", accountNumber)
                .addValue("customer", kyc.getCustomerId())
                .addValue("ref", kyc.getKycReference()));
        events.accountOpened(kyc.getCustomerId(), accountNumber, "CURRENT_EUR", kyc.getKycReference(), "EUR");
    }
}

package com.dss26.customer.profile.profile;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.function.Function;

/**
 * Which fields an update actually changed, as the snake_case names published
 * in customer.profile.updated.v1 (consumers such as sanctions screening decide
 * from these names whether to act).
 */
public final class ChangedFields {

    private record Field(String name, Function<Profile, Object> getter) {
    }

    private static final List<Field> FIELDS = List.of(
            new Field("first_name", Profile::firstName),
            new Field("last_name", Profile::lastName),
            new Field("date_of_birth", Profile::dateOfBirth),
            new Field("nationality", Profile::nationality),
            new Field("email", Profile::email),
            new Field("phone", Profile::phone),
            new Field("address", Profile::address),
            new Field("marketing_email", Profile::marketingEmail),
            new Field("marketing_sms", Profile::marketingSms));

    private ChangedFields() {
    }

    public static List<String> between(Profile before, Profile after) {
        List<String> changed = new ArrayList<>();
        for (Field f : FIELDS) {
            if (!Objects.equals(f.getter().apply(before), f.getter().apply(after))) {
                changed.add(f.name());
            }
        }
        return changed;
    }
}

