package com.dss26.cards.statements;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Runs one job and exits; scheduled by the platform (Kubernetes CronJob):
 * monthlyStatementJob on the 1st at 03:00, transactionReconciliationJob nightly.
 */
@SpringBootApplication
public class CardStatementsApplication {

    public static void main(String[] args) {
        System.exit(SpringApplication.exit(SpringApplication.run(CardStatementsApplication.class, args)));
    }
}

package com.dss26.cards.statements.config;

import com.zaxxer.hikari.HikariDataSource;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;

/**
 * Connections that are not the batch's own database: txn-history-builder's
 * read replica (statement lines), its primary (reconciliation writes only),
 * and the document archive bucket.
 */
@Configuration
public class InfrastructureConfig {

    @Bean
    NamedParameterJdbcTemplate txnHistoryJdbc(@Value("${statements.txn-history.read-url}") String url,
                                              @Value("${TXN_HISTORY_READER_USER}") String user,
                                              @Value("${TXN_HISTORY_READER_PASSWORD}") String password) {
        return new NamedParameterJdbcTemplate(pool("txn-history-replica", url, user, password, true));
    }

    @Bean
    NamedParameterJdbcTemplate txnHistoryWriteJdbc(@Value("${statements.txn-history.write-url}") String url,
                                                   @Value("${TXN_HISTORY_RECONCILER_USER}") String user,
                                                   @Value("${TXN_HISTORY_RECONCILER_PASSWORD}") String password) {
        return new NamedParameterJdbcTemplate(pool("txn-history-reconciler", url, user, password, false));
    }

    @Bean
    S3Client s3() {
        return S3Client.builder().region(Region.EU_WEST_1).build();
    }

    private static HikariDataSource pool(String name, String url, String user, String password, boolean readOnly) {
        HikariDataSource ds = new HikariDataSource();
        ds.setPoolName(name);
        ds.setJdbcUrl(url);
        ds.setUsername(user);
        ds.setPassword(password);
        ds.setReadOnly(readOnly);
        ds.setMaximumPoolSize(8);
        return ds;
    }
}

package com.dss26.cards.statements.events;

import com.dss26.cards.events.StatementGenerated;
import com.dss26.cards.statements.job.Model.CardStatement;
import org.apache.avro.specific.SpecificRecord;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;

import java.time.Instant;
import java.util.concurrent.TimeUnit;

/**
 * cards.statement.generated.v1, keyed by customer: notifications sends the
 * "your statement is ready" push, the apps list it under Statements.
 */
@Component
public class StatementGeneratedPublisher {

    static final String TOPIC = "cards.statement.generated.v1";
    private final KafkaTemplate<String, SpecificRecord> kafka;

    public StatementGeneratedPublisher(KafkaTemplate<String, SpecificRecord> kafka) {
        this.kafka = kafka;
    }

    public void generated(CardStatement statement) {
        StatementGenerated event = StatementGenerated.newBuilder()
                .setStatementId(statement.statementId())
                .setCustomerId(statement.cycle().customerId())
                .setCardToken(statement.cycle().cardToken())
                .setStatementPeriod(statement.cycle().period())
                .setClosingBalance(statement.closingBalance().doubleValue())
                .setCurrency(statement.cycle().currency())
                .setTransactionCount(statement.lines().size())
                .setGeneratedAt(Instant.now())
                .build();
        try {
            // Synchronous on purpose: the chunk only commits once the event is acknowledged.
            kafka.send(TOPIC, statement.cycle().customerId(), event).get(10, TimeUnit.SECONDS);
        } catch (Exception e) {
            throw new IllegalStateException("Could not publish statement " + statement.statementId(), e);
        }
    }
}

package com.dss26.cards.statements.job;

import org.springframework.batch.core.partition.support.Partitioner;
import org.springframework.batch.item.ExecutionContext;
import org.springframework.stereotype.Component;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** One partition per issuing BIN range, so the eight workers run in parallel on disjoint cards. */
@Component
public class BinRangePartitioner implements Partitioner {

    static final List<String[]> RANGES = List.of(
            new String[]{"400000", "419999"}, new String[]{"420000", "439999"},
            new String[]{"440000", "459999"}, new String[]{"460000", "499999"},
            new String[]{"510000", "529999"}, new String[]{"530000", "549999"},
            new String[]{"550000", "559999"}, new String[]{"222100", "272099"});

    @Override
    public Map<String, ExecutionContext> partition(int gridSize) {
        Map<String, ExecutionContext> partitions = new LinkedHashMap<>();
        for (String[] range : RANGES) {
            ExecutionContext ctx = new ExecutionContext();
            ctx.putString("binFrom", range[0]);
            ctx.putString("binTo", range[1]);
            partitions.put("bins-" + range[0] + "-" + range[1], ctx);
        }
        return partitions;
    }
}

package com.dss26.cards.statements.job;

import com.dss26.cards.statements.job.Model.StatementLine;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Component;

import java.sql.Timestamp;
import java.time.YearMonth;
import java.time.ZoneId;
import java.util.List;

/**
 * Reads card_transaction from the txn-history-builder read replica. The
 * schema belongs to txn-history-builder; we only read it.
 */
@Component
public class JdbcStatementLines implements StatementLines {

    private static final ZoneId PARIS = ZoneId.of("Europe/Paris");
    private final NamedParameterJdbcTemplate jdbc;

    public JdbcStatementLines(@Qualifier("txnHistoryJdbc") NamedParameterJdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public List<StatementLine> forCard(String cardToken, YearMonth period) {
        return jdbc.query("""
                SELECT auth_id, merchant_id, amount, status, authorised_at
                  FROM card_transaction
                 WHERE card_token = :card
                   AND authorised_at >= :from AND authorised_at < :to
                 ORDER BY authorised_at
                """,
                new MapSqlParameterSource("card", cardToken)
                        .addValue("from", Timestamp.from(period.atDay(1).atStartOfDay(PARIS).toInstant()))
                        .addValue("to", Timestamp.from(period.plusMonths(1).atDay(1).atStartOfDay(PARIS).toInstant())),
                (rs, n) -> new StatementLine(rs.getString("auth_id"), rs.getString("merchant_id"),
                        rs.getBigDecimal("amount"), rs.getString("status"), rs.getTimestamp("authorised_at").toInstant()));
    }
}

