package com.dss26.cards.statements.job;

import com.dss26.cards.statements.job.Model.CardStatement;
import com.dss26.cards.statements.job.Model.StatementCycle;
import com.dss26.cards.statements.job.Model.StatementLine;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.List;
import java.util.UUID;

/**
 * Builds one card's statement. Reversed authorisations are listed but do not
 * count towards the balance. A card with no activity and nothing owed gets no
 * statement (returning null filters the item).
 */
@Component
public class StatementItemProcessor implements ItemProcessor<StatementCycle, CardStatement> {

    private final StatementLines lines;

    public StatementItemProcessor(StatementLines lines) {
        this.lines = lines;
    }

    @Override
    public CardStatement process(StatementCycle cycle) {
        List<StatementLine> items = lines.forCard(cycle.cardToken(), YearMonth.parse(cycle.period()));
        if (items.isEmpty() && cycle.openingBalance().signum() == 0) {
            return null;
        }
        BigDecimal spent = items.stream()
                .filter(l -> !"REVERSED".equals(l.status()))
                .map(StatementLine::amount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        return new CardStatement(UUID.randomUUID().toString(), cycle, items, cycle.openingBalance().add(spent));
    }
}

package com.dss26.cards.statements.job;

import com.dss26.cards.statements.events.StatementGeneratedPublisher;
import com.dss26.cards.statements.job.Model.CardStatement;
import org.springframework.batch.item.Chunk;
import org.springframework.batch.item.ItemWriter;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import software.amazon.awssdk.core.sync.RequestBody;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;
import software.amazon.awssdk.services.s3.model.ServerSideEncryption;

/** Stores each PDF in the document archive, then announces it. */
@Component
public class StatementItemWriter implements ItemWriter<CardStatement> {

    private final S3Client s3;
    private final StatementPdfRenderer renderer;
    private final StatementGeneratedPublisher events;
    private final String bucket;

    public StatementItemWriter(S3Client s3, StatementPdfRenderer renderer, StatementGeneratedPublisher events,
                               @Value("${statements.archive-bucket}") String bucket) {
        this.s3 = s3;
        this.renderer = renderer;
        this.events = events;
        this.bucket = bucket;
    }

    @Override
    public void write(Chunk<? extends CardStatement> chunk) {
        for (CardStatement statement : chunk) {
            String key = "statements/%s/%s/%s.pdf".formatted(statement.cycle().period(),
                    statement.cycle().customerId(), statement.statementId());
            s3.putObject(PutObjectRequest.builder()
                            .bucket(bucket)
                            .key(key)
                            .contentType("application/pdf")
                            .serverSideEncryption(ServerSideEncryption.AWS_KMS)
                            .build(),
                    RequestBody.fromBytes(renderer.render(statement)));
            events.generated(statement);
        }
    }
}

package com.dss26.cards.statements.job;

import com.dss26.cards.statements.job.Model.CardStatement;
import com.dss26.cards.statements.job.Model.StatementCycle;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.configuration.annotation.StepScope;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.database.JdbcPagingItemReader;
import org.springframework.batch.item.database.Order;
import org.springframework.batch.item.database.builder.JdbcPagingItemReaderBuilder;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.task.SimpleAsyncTaskExecutor;
import org.springframework.jdbc.core.DataClassRowMapper;
import org.springframework.transaction.PlatformTransactionManager;
import software.amazon.awssdk.core.exception.SdkClientException;

import javax.sql.DataSource;
import java.util.Map;

@Configuration
public class StatementJobConfig {

    @Bean
    Job monthlyStatementJob(JobRepository jobRepository, Step statementManagerStep) {
        return new JobBuilder("monthlyStatementJob", jobRepository)
                .start(statementManagerStep)
                .build();
    }

    @Bean
    Step statementManagerStep(JobRepository jobRepository, Step statementWorkerStep, BinRangePartitioner partitioner) {
        return new StepBuilder("statementManagerStep", jobRepository)
                .partitioner("statementWorkerStep", partitioner)
                .step(statementWorkerStep)
                .gridSize(BinRangePartitioner.RANGES.size())
                .taskExecutor(new SimpleAsyncTaskExecutor("statements-"))
                .build();
    }

    @Bean
    Step statementWorkerStep(JobRepository jobRepository, PlatformTransactionManager tx,
                             JdbcPagingItemReader<StatementCycle> cycleReader, StatementItemProcessor processor,
                             StatementItemWriter writer) {
        return new StepBuilder("statementWorkerStep", jobRepository)
                .<StatementCycle, CardStatement>chunk(100, tx)
                .reader(cycleReader)
                .processor(processor)
                .writer(writer)
                .faultTolerant()
                .retry(SdkClientException.class)
                .retryLimit(3)
                .build();
    }

    /** Cards with a cycle closing in the period, one BIN range per partition. */
    @Bean
    @StepScope
    JdbcPagingItemReader<StatementCycle> cycleReader(DataSource dataSource,
                                                     @Value("#{jobParameters['period']}") String period,
                                                     @Value("#{stepExecutionContext['binFrom']}") String binFrom,
                                                     @Value("#{stepExecutionContext['binTo']}") String binTo) {
        return new JdbcPagingItemReaderBuilder<StatementCycle>()
                .name("cycleReader")
                .dataSource(dataSource)
                .selectClause("SELECT card_token, customer_id, period, opening_balance, currency")
                .fromClause("FROM statement_cycle")
                .whereClause("WHERE period = :period AND bin BETWEEN :binFrom AND :binTo")
                .parameterValues(Map.of("period", period, "binFrom", binFrom, "binTo", binTo))
                .sortKeys(Map.of("card_token", Order.ASCENDING))
                .pageSize(500)
                .rowMapper(new DataClassRowMapper<>(StatementCycle.class))
                .build();
    }
}

